package com.gym.fitness.module.cashshift.service;
import com.gym.fitness.module.cashshift.dto.CashShiftDtos.*;
import com.gym.fitness.module.cashshift.entity.*;
import com.gym.fitness.module.cashshift.repository.*;
import com.gym.fitness.common.constant.ErrorCode;
import com.gym.fitness.common.exception.BusinessException;
import com.gym.fitness.common.util.VenueMutationLock;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.domain.PageRequest;
import java.util.*;
import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
@Service @RequiredArgsConstructor
public class CashShiftService {
 private final CashShiftRepository shifts;private final CashShiftChannelRepository channels;private final CashShiftPaymentRepository payments;private final CashShiftEventRepository events;
 private final CashShiftScope scope;private final CashShiftLedger ledger;private final VenueMutationLock venueLock;private final JdbcTemplate jdbc;private final ObjectMapper json;
 private Clock businessClock=Clock.system(ZoneId.of("Asia/Shanghai"));
 private LocalDateTime now(){return LocalDateTime.now(businessClock).truncatedTo(ChronoUnit.MICROS);}
 static Map<String,Object> map(Object... a){var m=new LinkedHashMap<String,Object>();for(int i=0;i<a.length;i+=2)m.put((String)a[i],a[i+1]);return m;}
 static BigDecimal yuan(Long c){return c==null?null:BigDecimal.valueOf(c,2);}
 static BusinessException invalid(String m){return new BusinessException(ErrorCode.PARAM_ERROR,m);}
 static BusinessException conflict(String m){return new BusinessException(ErrorCode.OPERATION_NOT_ALLOWED,m);}
 private CashShiftEntity access(Long id){scope.require("CASH_SHIFT_READ");var s=shifts.findById(id).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"班次不存在"));scope.access(s.getVenueId());return s;}
 @Transactional(readOnly=true) public Map<String,Object> detail(Long id){return detail(access(id));}
 @Transactional public Map<String,Object> open(OpenRequest r){scope.lockActor("CASH_SHIFT_WRITE");Long venue=scope.venue(r.venueId());String fp=requestFingerprint("OPEN",null,r);var replay=events.findByActorIdAndRequestKey(scope.actor(),r.idempotencyKey());if(replay.isPresent()){var s=access(replay.get().getShiftId());same(replay.get(),fp);return detail(s);}if(venue==null)throw invalid("请选择门店");venueLock.acquire(venue);
  if(!"ACTIVE".equals(jdbc.queryForObject("select status from venue where id=?",String.class,venue)))throw conflict("门店已停业");if(shifts.current(venue).isPresent())throw conflict("本店已有未交班班次");
  long opening=ledger.max(venue);var prior=shifts.closed(venue,PageRequest.of(0,1));long baseline=prior.isEmpty()?opening:prior.get(0).getCutoffPaymentId();
  var s=new CashShiftEntity();s.setVenueId(venue);s.setActiveVenueId(venue);s.setShiftNo("CS-"+UUID.randomUUID());s.setBusinessDate(now().toLocalDate());s.setStatus("OPEN");s.setVersion(0L);s.setOpenedBy(scope.actor());s.setOpenedAt(now());s.setNote(r.note());s.setBaselinePaymentId(baseline);s.setOpeningPaymentId(opening);s.setSystemReceipts(0L);s.setSystemRefunds(0L);shifts.saveAndFlush(s);event(s,"OPEN",r.note(),null,r.idempotencyKey(),fp);return detail(s);
 }
 private String requestFingerprint(String action,Long id,Object body){try{return CashShiftLedger.sha(action+":"+id+":"+json.writeValueAsString(body));}catch(Exception e){throw new IllegalStateException(e);}}
 private void same(CashShiftEventEntity e,String fp){if(!fp.equals(e.getRequestFingerprint()))throw invalid("请求键已用于其他内容");}
 private void event(CashShiftEntity s,String action,String content,String changes,String key,String fp){var e=new CashShiftEventEntity();e.setShiftId(s.getId());e.setActorId(scope.actor());e.setAction(action);e.setContent(content);e.setChangesJson(changes);e.setCreatedAt(now());e.setRequestKey(key);e.setRequestFingerprint(fp);events.saveAndFlush(e);}
 private Map<String,Object> channel(String name,long sr,long sf,Long ar,Long af){return map("channel",name,"systemReceipts",yuan(sr),"systemRefunds",yuan(sf),"systemNet",yuan(sr-sf),"actualReceipts",yuan(ar),"actualRefunds",yuan(af),"actualNet",ar==null?null:yuan(ar-af),"receiptsDifference",ar==null?null:yuan(ar-sr),"refundsDifference",af==null?null:yuan(af-sf),"netDifference",ar==null?null:yuan(ar-af-sr+sf));}
 private Map<String,Object> payment(CashShiftPaymentEntity p){return map("id",p.getId()==null?p.getPaymentTransactionId():p.getId(),"paymentTransactionId",p.getPaymentTransactionId(),"transactionNo",p.getTransactionNo(),"orderId",p.getOrderId(),"transactionType",p.getTransactionType(),"channel",p.getChannel(),"amount",yuan(p.getAmountCents()),"occurredAt",p.getOccurredAt(),"operatorId",p.getOperatorId(),"carriedOver",p.getCarriedOver());}
 private Map<String,Object> shift(CashShiftEntity s,Map<Long,String> names){return shift(s,names,Map.of(s.getVenueId(),jdbc.queryForObject("select name from venue where id=?",String.class,s.getVenueId())));}
 private Map<String,Object> shift(CashShiftEntity s,Map<Long,String> names,Map<Long,String> venueNames){return map("id",s.getId(),"shiftNo",s.getShiftNo(),"venueId",s.getVenueId(),"venueName",venueNames.get(s.getVenueId()),"businessDate",s.getBusinessDate(),"status",s.getStatus(),"version",s.getVersion(),"openedBy",s.getOpenedBy(),"openedName",names.get(s.getOpenedBy()),"openedAt",s.getOpenedAt(),"submittedBy",s.getSubmittedBy(),"submittedName",names.get(s.getSubmittedBy()),"closedAt",s.getClosedAt(),"reviewedBy",s.getReviewedBy(),"reviewedName",names.get(s.getReviewedBy()),"reviewedAt",s.getReviewedAt(),"reviewReason",s.getReviewReason(),"note",s.getNote(),"differenceReason",s.getDifferenceReason(),"handoverNote",s.getHandoverNote(),"baselinePaymentId",s.getBaselinePaymentId(),"openingPaymentId",s.getOpeningPaymentId(),"cutoffPaymentId",s.getCutoffPaymentId(),"ledgerFingerprint",s.getLedgerFingerprint(),"systemReceipts",yuan(s.getSystemReceipts()),"systemRefunds",yuan(s.getSystemRefunds()),"systemNet",yuan(s.getSystemReceipts()-s.getSystemRefunds()),"actualReceipts",yuan(s.getActualReceipts()),"actualRefunds",yuan(s.getActualRefunds()),"actualNet",s.getActualReceipts()==null?null:yuan(s.getActualReceipts()-s.getActualRefunds()),"netDifference",s.getActualReceipts()==null?null:yuan(s.getActualReceipts()-s.getActualRefunds()-s.getSystemReceipts()+s.getSystemRefunds()));}
 private Map<Long,String> names(Collection<Long> ids){var result=new HashMap<Long,String>();var unique=ids.stream().filter(Objects::nonNull).distinct().toList();if(!unique.isEmpty())jdbc.query("select id,coalesce(real_name,username) name from sys_user where id in ("+String.join(",",Collections.nCopies(unique.size(),"?"))+")",rs->{result.put(rs.getLong("id"),rs.getString("name"));},unique.toArray());return result;}
 private Map<String,Object> detail(CashShiftEntity s){boolean open="OPEN".equals(s.getStatus());var ps=open?ledger.candidates(s.getVenueId(),s.getBaselinePaymentId(),s.getOpeningPaymentId(),ledger.max(s.getVenueId())):payments.findByShiftIdOrderByPaymentTransactionIdAsc(s.getId(),PageRequest.of(0,100)).getContent();long paymentTotal=open?ps.size():payments.countByShiftId(s.getId());var cs=open?CashShiftLedger.totals(ps).entrySet().stream().map(e->channel(e.getKey(),e.getValue()[0],e.getValue()[1],null,null)).toList():channels.findByShiftIdOrderByIdAsc(s.getId()).stream().map(c->channel(c.getChannel(),c.getSystemReceipts(),c.getSystemRefunds(),c.getActualReceipts(),c.getActualRefunds())).toList();var es=events.findByShiftIdOrderByIdAsc(s.getId());var ids=new ArrayList<Long>();ids.add(s.getOpenedBy());ids.add(s.getSubmittedBy());ids.add(s.getReviewedBy());es.forEach(e->ids.add(e.getActorId()));var names=names(ids);long sr=open?ps.stream().filter(p->"PAYMENT".equals(p.getTransactionType())).mapToLong(CashShiftPaymentEntity::getAmountCents).sum():s.getSystemReceipts(),sf=open?ps.stream().filter(p->"REFUND".equals(p.getTransactionType())).mapToLong(CashShiftPaymentEntity::getAmountCents).sum():s.getSystemRefunds();var view=shift(s,names);view.put("systemReceipts",yuan(sr));view.put("systemRefunds",yuan(sf));view.put("systemNet",yuan(sr-sf));return map("shift",view,"preview",map("ledgerFingerprint",open?CashShiftLedger.fingerprint(ps):s.getLedgerFingerprint(),"paymentCount",paymentTotal,"carriedOverCount",open?ps.stream().filter(CashShiftPaymentEntity::getCarriedOver).count():payments.countByShiftIdAndCarriedOverTrue(s.getId()),"historicalExcludedCount",ledger.historical(s.getVenueId(),jdbc.queryForObject("select baseline_payment_id from cash_shift where venue_id=? order by id asc limit 1",Long.class,s.getVenueId())),"channels",cs,"systemReceipts",yuan(sr),"systemRefunds",yuan(sf),"systemNet",yuan(sr-sf)),"channels",cs,"audit",es.stream().map(e->map("id",e.getId(),"action",e.getAction(),"actorName",names.get(e.getActorId()),"content",e.getContent(),"changesJson",e.getChangesJson(),"createdAt",e.getCreatedAt())).toList(),"payments",ps.stream().limit(100).map(this::payment).toList(),"paymentTotal",paymentTotal);}

 private CashShiftEntity lock(Long id){var vs=jdbc.queryForList("select venue_id from cash_shift where id=?",Long.class,id);if(vs.isEmpty())throw new BusinessException(ErrorCode.NOT_FOUND,"班次不存在");scope.access(vs.get(0));venueLock.acquire(vs.get(0));return shifts.locked(id).orElseThrow(()->new BusinessException(ErrorCode.NOT_FOUND,"班次不存在"));}
 private void submitActor(CashShiftEntity s){if(scope.manager())return;boolean allowed=Objects.equals(s.getOpenedBy(),scope.actor())||("RETURNED".equals(s.getStatus())&&Objects.equals(s.getSubmittedBy(),scope.actor()));if(!allowed)throw CashShiftScope.forbidden();}
 private boolean replay(CashShiftEntity s,String key,String fp){var e=events.findByActorIdAndRequestKey(scope.actor(),key);if(e.isEmpty())return false;if(!Objects.equals(e.get().getShiftId(),s.getId()))throw invalid("请求键已用于其他班次");same(e.get(),fp);return true;}
 private void version(CashShiftEntity s,Long expected){if(!Objects.equals(s.getVersion(),expected))throw conflict("班次已变化，请重新载入核对");}
 private long cents(BigDecimal amount){if(amount==null||amount.signum()<0||amount.scale()>2||amount.compareTo(new BigDecimal("9999999999.99"))>0)throw invalid("实际金额需非负、最多两位小数且不超过9999999999.99");return amount.movePointRight(2).longValueExact();}
 @Transactional public Map<String,Object> submit(Long id,SubmitRequest r){scope.lockActor("CASH_SHIFT_WRITE");var s=lock(id);submitActor(s);String fp=requestFingerprint("SUBMIT",id,r);if(replay(s,r.idempotencyKey(),fp))return detail(s);version(s,r.expectedVersion());boolean opening="OPEN".equals(s.getStatus());if(!opening&&!"RETURNED".equals(s.getStatus()))throw conflict("当前班次不能提交");
  long cutoff=opening?ledger.max(s.getVenueId()):s.getCutoffPaymentId();var ps=opening?ledger.candidates(s.getVenueId(),s.getBaselinePaymentId(),s.getOpeningPaymentId(),cutoff):List.<CashShiftPaymentEntity>of();String ledgerFp=opening?CashShiftLedger.fingerprint(ps):s.getLedgerFingerprint();if(!ledgerFp.equals(r.ledgerFingerprint()))throw conflict("流水已变化，请重新载入并核对全部渠道");
  var totals=opening?CashShiftLedger.totals(ps):new LinkedHashMap<String,long[]>();var existing=channels.findByShiftIdOrderByIdAsc(id);if(!opening)existing.forEach(c->totals.put(c.getChannel(),new long[]{c.getSystemReceipts(),c.getSystemRefunds()}));var actual=new LinkedHashMap<String,long[]>();for(var c:r.channels()){String name=CashShiftLedger.channel(c.channel());if(!totals.containsKey(name)||actual.containsKey(name))throw invalid("渠道不属于当前班次或重复");actual.put(name,new long[]{cents(c.actualReceipts()),cents(c.actualRefunds())});}if(actual.size()!=totals.size())throw invalid("请逐行明确填写全部渠道实际收退款");boolean difference=totals.entrySet().stream().anyMatch(e->e.getValue()[0]!=actual.get(e.getKey())[0]||e.getValue()[1]!=actual.get(e.getKey())[1]);if(difference&&(r.differenceReason()==null||r.differenceReason().isBlank()))throw invalid("收款或退款有差异，必须填写差异说明");
  var before=existing.stream().map(c->channel(c.getChannel(),c.getSystemReceipts(),c.getSystemRefunds(),c.getActualReceipts(),c.getActualRefunds())).toList();String previousReason=s.getDifferenceReason(),previousNote=s.getHandoverNote();long sr=0,sf=0,ar=0,af=0;for(var entry:totals.entrySet()){String name=entry.getKey();var t=entry.getValue();var a=actual.get(name);var c=opening?new CashShiftChannelEntity():existing.stream().filter(x->name.equals(x.getChannel())).findFirst().orElseThrow();c.setShiftId(id);c.setChannel(name);c.setSystemReceipts(t[0]);c.setSystemRefunds(t[1]);c.setActualReceipts(a[0]);c.setActualRefunds(a[1]);channels.save(c);sr=Math.addExact(sr,t[0]);sf=Math.addExact(sf,t[1]);ar=Math.addExact(ar,a[0]);af=Math.addExact(af,a[1]);}
  if(opening){for(var p:ps){p.setShiftId(id);payments.save(p);}s.setClosedAt(now());s.setCutoffPaymentId(cutoff);s.setLedgerFingerprint(ledgerFp);s.setActiveVenueId(null);s.setSystemReceipts(sr);s.setSystemRefunds(sf);}s.setActualReceipts(ar);s.setActualRefunds(af);s.setStatus("SUBMITTED");s.setSubmittedBy(scope.actor());s.setDifferenceReason(r.differenceReason());s.setHandoverNote(r.handoverNote());s.setVersion(Math.addExact(s.getVersion(),1L));shifts.saveAndFlush(s);channels.flush();payments.flush();var after=channels.findByShiftIdOrderByIdAsc(id).stream().map(c->channel(c.getChannel(),c.getSystemReceipts(),c.getSystemRefunds(),c.getActualReceipts(),c.getActualRefunds())).toList();String changes;try{changes=json.writeValueAsString(map("before",before,"after",after,"previousDifferenceReason",previousReason,"differenceReason",r.differenceReason(),"previousHandoverNote",previousNote,"handoverNote",r.handoverNote()));}catch(Exception e){throw new IllegalStateException(e);}event(s,opening?"SUBMIT":"RESUBMIT",r.handoverNote(),changes,r.idempotencyKey(),fp);return detail(s);
 }
 @Transactional public Map<String,Object> review(Long id,ReviewRequest r){scope.lockActor("CASH_SHIFT_REVIEW");var s=lock(id);if(Objects.equals(scope.actor(),s.getSubmittedBy()))throw CashShiftScope.forbidden();String fp=requestFingerprint("REVIEW",id,r);if(replay(s,r.idempotencyKey(),fp))return detail(s);version(s,r.expectedVersion());if(!"SUBMITTED".equals(s.getStatus()))throw conflict("只能复核待审班次");if(!Set.of("APPROVE","RETURN").contains(r.decision()))throw invalid("复核动作不正确");if("RETURN".equals(r.decision())&&(r.reason()==null||r.reason().isBlank()))throw invalid("退回必须填写原因");s.setStatus("APPROVE".equals(r.decision())?"APPROVED":"RETURNED");s.setReviewedBy(scope.actor());s.setReviewedAt(now());s.setReviewReason(r.reason());s.setVersion(Math.addExact(s.getVersion(),1));shifts.saveAndFlush(s);event(s,r.decision(),r.reason(),null,r.idempotencyKey(),fp);return detail(s);}
 private void page(int page,int size){if(page<1||size<1||size>100)throw invalid("分页参数不正确");}
 @Transactional(readOnly=true) public Map<String,Object> paymentPage(Long id,int page,int size){page(page,size);var s=access(id);if("OPEN".equals(s.getStatus())){var ps=ledger.candidatePage(s.getVenueId(),s.getBaselinePaymentId(),s.getOpeningPaymentId(),ledger.max(s.getVenueId()),page,size);return map("records",ps.records().stream().map(this::payment).toList(),"total",ps.total(),"page",page,"size",size);}var ps=payments.findByShiftIdOrderByPaymentTransactionIdAsc(id,PageRequest.of(page-1,size));return map("records",ps.getContent().stream().map(this::payment).toList(),"total",ps.getTotalElements(),"page",page,"size",size);}
 @Transactional(readOnly=true)
 public Map<String,Object> workbench(Long requested,LocalDate day,String status,int page,int size){
  Long venue=scope.venue(requested);page(page,size);
  if(!Set.of("ALL","OPEN","SUBMITTED","RETURNED","APPROVED").contains(status))throw invalid("状态筛选不正确");
  if(day==null)day=now().toLocalDate();
  var current=venue==null?null:shifts.current(venue).orElse(null);
  var result=shifts.filtered(venue,day,status,PageRequest.of(page-1,size));
  var displayed=new ArrayList<>(result.getContent());if(current!=null)displayed.add(current);
  var ids=new ArrayList<Long>();for(var row:displayed){ids.add(row.getOpenedBy());ids.add(row.getSubmittedBy());ids.add(row.getReviewedBy());}
  var names=names(ids);
  Long visibleVenue=scope.venue(null);
  var vs=visibleVenue==null?jdbc.queryForList("select id,name from venue order by id"):jdbc.queryForList("select id,name from venue where id=? order by id",visibleVenue);
  var venueNames=new HashMap<Long,String>();vs.forEach(v->venueNames.put(((Number)v.get("id")).longValue(),(String)v.get("name")));
  var summary=dailySummary(venue,day);
  var aggregate=dailyChannels(venue,day);
  var records=result.getContent().stream().map(row->shift(row,names,venueNames)).toList();
  var currentView=current==null?null:shift(current,names,venueNames);
  var liveViews=new ArrayList<>(records);if(currentView!=null)liveViews.add(currentView);liveAmounts(liveViews);
  return map("businessDate",day,"venues",vs,"selectedVenueId",venue,"currentShift",currentView,"summary",summary,"channels",aggregate,"shifts",map("records",records,"total",result.getTotalElements(),"page",page,"size",size));
 }
 private Object[] dailyArgs(Long venue,LocalDate day){return venue==null?new Object[]{java.sql.Date.valueOf(day)}:new Object[]{java.sql.Date.valueOf(day),venue};}
 private String dailyWhere(Long venue){return " s.business_date=?"+(venue==null?"":" and s.venue_id=?");}
 private long scalar(Map<String,Object> row,String key){return new BigDecimal(row.get(key).toString()).longValueExact();}
 private Map<String,Object> dailySummary(Long venue,LocalDate day){
  var row=jdbc.queryForMap("""
   select count(*) shift_count,
    coalesce(sum(case when s.status='OPEN' then 1 else 0 end),0) open_count,
    coalesce(sum(case when s.status='SUBMITTED' then 1 else 0 end),0) pending_count,
    coalesce(sum(case when s.status='RETURNED' then 1 else 0 end),0) returned_count,
    coalesce(sum(case when s.status='APPROVED' then 1 else 0 end),0) approved_count,
    coalesce(sum(case when s.status<>'OPEN' then s.system_receipts else 0 end),0) system_receipts,
    coalesce(sum(case when s.status<>'OPEN' then s.system_refunds else 0 end),0) system_refunds,
    coalesce(sum(case when s.status<>'OPEN' then s.actual_receipts else 0 end),0) actual_receipts,
    coalesce(sum(case when s.status<>'OPEN' then s.actual_refunds else 0 end),0) actual_refunds,
    coalesce(sum(case when s.status='APPROVED' then s.actual_receipts-s.actual_refunds else 0 end),0) approved_net
   from cash_shift s where
   """+dailyWhere(venue),dailyArgs(venue,day));
  long sr=scalar(row,"system_receipts"),sf=scalar(row,"system_refunds"),ar=scalar(row,"actual_receipts"),af=scalar(row,"actual_refunds");
  return map("shiftCount",scalar(row,"shift_count"),"openCount",scalar(row,"open_count"),"pendingReviewCount",scalar(row,"pending_count"),"returnedCount",scalar(row,"returned_count"),"approvedCount",scalar(row,"approved_count"),"systemReceipts",yuan(sr),"systemRefunds",yuan(sf),"systemNet",yuan(sr-sf),"actualReceipts",yuan(ar),"actualRefunds",yuan(af),"actualNet",yuan(ar-af),"netDifference",yuan(ar-af-sr+sf),"approvedNet",yuan(scalar(row,"approved_net")));
 }
 private List<Map<String,Object>> dailyChannels(Long venue,LocalDate day){
  var totals=new LinkedHashMap<String,long[]>();for(String name:List.of("CASH","WECHAT","ALIPAY","CARD"))totals.put(name,new long[4]);
  jdbc.query("select c.channel,sum(c.system_receipts) system_receipts,sum(c.system_refunds) system_refunds,sum(c.actual_receipts) actual_receipts,sum(c.actual_refunds) actual_refunds from cash_shift_channel c join cash_shift s on s.id=c.shift_id where s.status<>'OPEN' and"+dailyWhere(venue)+" group by c.channel order by c.channel",rs->{totals.put(rs.getString("channel"),new long[]{rs.getBigDecimal("system_receipts").longValueExact(),rs.getBigDecimal("system_refunds").longValueExact(),rs.getBigDecimal("actual_receipts").longValueExact(),rs.getBigDecimal("actual_refunds").longValueExact()});},dailyArgs(venue,day));
  return totals.entrySet().stream().map(e->channel(e.getKey(),e.getValue()[0],e.getValue()[1],e.getValue()[2],e.getValue()[3])).toList();
 }

 private void liveAmounts(List<Map<String,Object>> views){var ids=views.stream().filter(v->"OPEN".equals(v.get("status"))).map(v->(Long)v.get("id")).distinct().toList();if(ids.isEmpty())return;var amounts=new HashMap<Long,long[]>();jdbc.query("select s.id,sum(case when p.transaction_type='PAYMENT' then p.amount else 0 end) receipts,sum(case when p.transaction_type='REFUND' then p.amount else 0 end) refunds from cash_shift s join sales_order o on o.venue_id=s.venue_id join payment_transaction p on p.order_id=o.id where s.id in ("+String.join(",",Collections.nCopies(ids.size(),"?"))+") and p.id>s.baseline_payment_id and p.status='SUCCESS' and p.transaction_type in ('PAYMENT','REFUND') group by s.id",rs->{amounts.put(rs.getLong("id"),new long[]{rs.getBigDecimal("receipts").movePointRight(2).longValueExact(),rs.getBigDecimal("refunds").movePointRight(2).longValueExact()});},ids.toArray());for(var v:views)if("OPEN".equals(v.get("status"))){var a=amounts.getOrDefault(v.get("id"),new long[2]);v.put("systemReceipts",yuan(a[0]));v.put("systemRefunds",yuan(a[1]));v.put("systemNet",yuan(a[0]-a[1]));}}
}
